/* @socom-skeleton stub BodySetup__5CBodyFPQ23zdb5CNodeP10CZBodyPart */
CZBodyPart * CBody::BodySetup(zdb::CNode *node, CZBodyPart *parent)
{
	/* 0x1e35a0: a part for node (when its name is a body part) and, below it, a part for
	 * each named child and the subtree under each of those; parts are stored by id */
	CZBodyPart* part = NewBodyPart(node, parent);

	if (part == NULL)
		return NULL;

	m_body_parts[part->m_id] = part;

	for (std::vector<zdb::CNode*>::iterator i = node->m_child.begin(); i != node->m_child.end(); i++)
	{
		zdb::CNode* child = *i;
		CZBodyPart* childpart = NewBodyPart(child, part);

		if (childpart == NULL)
			continue;

		m_body_parts[childpart->m_id] = childpart;

		for (std::vector<zdb::CNode*>::iterator j = child->m_child.begin(); j != child->m_child.end(); j++)
			BodySetup(*j, childpart);
	}

	return part;
}

/* @socom-skeleton stub NewBodyPart__5CBodyFPQ23zdb5CNodeP10CZBodyPart */
CZBodyPart * CBody::NewBodyPart(zdb::CNode *node, CZBodyPart *parent)
{
	/* 0x1e34b0: a part for a node named as a body part (BodyId >= 0; a NULL node takes
	 * NullNode's id) */
	s32 id = NullNode();

	if (node != NULL)
	{
		id = BodyId(node->m_name);

		if (id < 0)
			return NULL;
	}

	CZBodyPart* part = new CZBodyPart(node);
	part->m_parent = parent;
	part->m_id = (s16)id;
	return part;
}

/* @socom-skeleton stub AddBodyPart__5CBodyFPQ23zdb5CNodeP10CZBodyPart */
CZBodyPart * CBody::AddBodyPart(zdb::CNode *node, CZBodyPart *parent)
{
	/* 0x1e33e0: one part (as NewBodyPart), stored by id */
	CZBodyPart* part = NewBodyPart(node, parent);

	if (part != NULL)
		m_body_parts[part->m_id] = part;

	return part;
}

/* @socom-skeleton stub AttachAuxNode__5CBodyFPQ23zdb5CNodeP10CZBodyPartPC6CPnt3DPC6CPnt3D */
CZBodyPart * CBody::AttachAuxNode(zdb::CNode *node, CZBodyPart *parent, const CPnt3D *pos, const CPnt3D *rot)
{
	/* 0x1e32d0: a new aux part for node under parent (node becomes a child of the
	 * parent's node), posed at pos / the euler rot. ELF quirk: parent is not NULL-checked. */
	CQuat quat;
	QFromRot(&quat, rot);
	CZBodyPart *part = new CZBodyPart(node);
	part->m_parent = parent;
	parent->m_node->AddChild(node);
	part->m_node = node;
	m_body_parts_aux.push_back(part);
	part->m_pos = *pos;
	part->m_rot = quat;
	zdb::CNode *partnode = part->m_node;
	partnode->SetPosition(part->m_pos.x, part->m_pos.y, part->m_pos.z);
	partnode->SetRotation(&part->m_rot);
	return part;
}

/* @socom-skeleton stub AttachAuxPart__5CBodyFP10CZBodyPartP10CZBodyPart */
CZBodyPart * CBody::AttachAuxPart(CZBodyPart *part, CZBodyPart *parent)
{
	/* 0x1e3240: an aux part under parent (its node becomes a child of parent's node) */
	part->m_parent = parent;
	zdb::CNode *node = part->m_node;

	if (parent != NULL)
		parent->m_node->AddChild(node);

	part->m_node = node;
	m_body_parts_aux.push_back(part);
	return part;
}

/* @socom-skeleton stub FindAuxNode__5CBodyFPCcb */
zdb::CNode * CBody::FindAuxNode(const char *name, bool nested)
{
	/* 0x1e3160: the aux part node named name (not nested), else the first aux node with a
	 * descendant of that name */
	for (std::vector<CZBodyPart*>::iterator it = m_body_parts_aux.begin(); it != m_body_parts_aux.end(); ++it)
	{
		zdb::CNode *node = (*it)->m_node;

		if (!nested && node != NULL && strcmp(name, node->m_name) == 0)
			return node;

		zdb::CNode *child = node != NULL ? node->FindChild(name, true) : NULL;

		if (child != NULL)
			return child;
	}

	return NULL;
}

/* @socom-skeleton stub FindBodyPart__5CBodyFi */
CZBodyPart * CBody::FindBodyPart(int id)
{
	/* 0x1e3110 (CZSealBody::Action): the first body part with that id, NULL if none */
	for (std::vector<CZBodyPart*>::iterator it = m_body_parts.begin(); it != m_body_parts.end(); ++it)
	{
		if (*it != NULL && (*it)->m_id == id)
			return *it;
	}

	return NULL;
}

/* @socom-skeleton body FindPart__5CBodyCFPCc */
CZBodyPart * CBody::FindPart(const char *name) const
{
	/* 0x1e3070: the part whose node has that name (a part without a node is "") */
	for (std::vector<CZBodyPart*>::const_iterator it = m_body_parts.begin(); it != m_body_parts.end(); it++)
	{
		CZBodyPart* part = *it;

		if (part == NULL)
			continue;

		const char* partname = part->m_node != NULL ? part->m_node->m_name : "";

		if (strcmp(partname, name) == 0)
			return part;
	}

	return NULL;
}

/* @socom-skeleton stub BodyAddAnim__5CBodyFPCcbi */
CZBodyAnim * CBody::BodyAddAnim(const char *name, bool looped, int id)
{
	/* 0x1e2cd0: load the script; map each body part to its SI object by node name (the
	 * skel_root part is the base part), then the unused objects (not "do_not_use") by
	 * BodyId. A failed load still takes a NULL slot. The object list is built only while the
	 * script common is not ready. */
	CZBodyAnim *anim = new CZBodyAnim(name);

	if (anim == NULL || !anim->m_isLoaded)
	{
		AddAnim(NULL, id, -1);

		if (anim != NULL)
			delete anim;

		return NULL;
	}

	s16 basepart = -1;
	anim->m_looped = looped;

	for (std::vector<CZBodyPart*>::iterator it = m_body_parts.begin(); it != m_body_parts.end(); ++it)
	{
		CZBodyPart *part = *it;

		if (part == NULL)
			continue;

		const char *partname = part->m_node != NULL ? part->m_node->m_name : "";
		CZSIObject *object = anim->GetObject(partname, true);
		CZSIScriptCommon *common = anim->m_pCommon;

		if (object == NULL)
		{
			if (common->m_objects_ready == 0)
				common->m_objects_for_body.push_back(NULL);
		}
		else
		{
			s16 partid = part->m_id;

			if (common->m_objects_ready == 0)
				common->m_objects_for_body.push_back(object);

			if (anim->m_pCommon->m_objects_ready == 0)
				object->m_body_part_id = part->m_id;

			if (strcmp(partname, "skel_root") == 0)
				basepart = partid;
		}
	}

	CZSIScriptCommon *common = anim->m_pCommon;

	if (common->m_objects_ready == 0)
	{
		CZSIObject *object = common->m_pObjects;

		for (s32 i = 0; i < anim->m_pCommon->m_nObjects; i++, object++)
		{
			if (object != NULL && !object->m_inUse && strcmp(object->m_pName, "do_not_use") != 0)
			{
				if (anim->m_pCommon->m_objects_ready == 0)
					anim->m_pCommon->m_objects_for_body.push_back(object);

				object->m_body_part_id = BodyId(object->m_pName);
			}
		}
	}

	AddAnim(anim, id, -1);
	anim->m_basepart = basepart;
	return anim;
}

