		first.y = object->m_positionData[1];
		first.z = object->m_positionData[2];
		last.x = object->m_positionData[lastframe * 3 + 0];
		last.y = object->m_positionData[lastframe * 3 + 1];
		last.z = object->m_positionData[lastframe * 3 + 2];
