	if (!anim->m_looped)
	{
		f32 frames = (f32)anim->m_pCommon->m_nFrames;

		if (!(frames <= 1.0f))
			loop = (frames - 1.0f) / frames;
	}

	f32 step = dT / (anim->m_tf * loop);
	f32 now = m_anim->m_tfrac;

	if (m_state == -1)
	{
		f32 end = now - step;
		return !(t < end || now < t);
	}

	f32 end = now + step;

	if (now <= end)
		return now <= t && t <= end;

	return now - loop <= t && t <= end;
